CREATE TABLE `business_unit_date_overrides` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`public_id` CHAR(36) NOT NULL,`tenant_id` BIGINT UNSIGNED NOT NULL,`unit_id` BIGINT UNSIGNED NOT NULL,`date` DATE NOT NULL,`type` ENUM('EXCEPTION', 'HOLIDAY') NOT NULL,`closed` BOOLEAN NOT NULL DEFAULT FALSE,`starts_at` CHAR(5) NULL,`ends_at` CHAR(5) NULL,`title` VARCHAR(160) NULL,`active` BOOLEAN NOT NULL DEFAULT TRUE,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),UNIQUE INDEX `business_unit_date_overrides_public_id_key` (`public_id`),INDEX `business_unit_date_overrides_tenant_id_unit_id_date_active_idx` (`tenant_id`,`unit_id`,`date`,`active`),INDEX `business_unit_date_overrides_tenant_id_unit_id_type_date_idx` (`tenant_id`,`unit_id`,`type`,`date`),CONSTRAINT `business_unit_date_overrides_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `business_unit_date_overrides_unit_id_fkey` FOREIGN KEY (`unit_id`) REFERENCES `business_units`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
